#include "autotune.hpp"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <cassert>
#include <iostream>
#include <fstream>
int main(int argc,char**argv){QCoreApplication app(argc,argv);QTemporaryDir temp;J calls=J::array();auto callback=[&](const std::string& action,const J& p)->J{calls.push_back({{"action",action},{"params",p}});if(action=="media.status")return {{"ok",true},{"payload",{{"hardware_eq_enabled",false},{"software_eq_enabled",true},{"hardware_eq_db",{0,0,0,0,0}},{"dsp",{{"available",true}}},{"audio_running",false}}}};return {{"ok",true}};};AutoTune tune(callback,temp.path());auto start=tune.run({{"operation","start"}});assert(start["active"]==true&&calls.size()==1);tune.run({{"operation","b"}});auto audio=calls.back();assert(audio["action"]=="media.show");auto path=audio["params"]["url"].get<std::string>();std::ifstream f(path,std::ios::binary);std::string wav((std::istreambuf_iterator<char>(f)),{});assert(wav.size()==44+72000*4);assert(wav.substr(0,4)=="RIFF"&&wav.substr(8,4)=="WAVE");int peak=0;for(size_t i=44;i<wav.size();i+=4){int16_t v=uint16_t(uint8_t(wav[i]))|(uint16_t(uint8_t(wav[i+1]))<<8);assert(wav[i]==wav[i+2]&&wav[i+1]==wav[i+3]);peak=std::max(peak,std::abs(int(v)));}assert(peak>1700&&peak<1900);assert(wav[44]==0&&wav[45]==0&&wav[wav.size()-4]==0&&wav[wav.size()-3]==0);bool invalid=false;try{tune.run({{"operation","choose"},{"choice","pretend"}});}catch(...){invalid=true;}assert(invalid&&tune.status()["trial"]==0);for(int i=0;i<10;i++)tune.run({{"operation","choose"},{"choice","b"}});assert(!tune.status()["active"].get<bool>());assert(tune.status()["profile_a"]==J({4,4,4,4,4}));assert(QFile::exists(temp.path()+"/preferred-eq.json"));for(auto call:calls)if(call["action"]=="media.control")assert(call["params"].value("operation",std::string())!="volume");AutoTune cancel(callback,temp.path());cancel.run({{"operation","start"}});cancel.run({{"operation","b"}});cancel.run({{"operation","cancel"}});assert(!cancel.status()["active"].get<bool>());bool badTone=false;try{cancel.generatedTone({{"frequency_hz",9000}});}catch(...){badTone=true;}assert(badTone);AutoTune resume(callback,temp.path());AutoTune source(callback,temp.path());source.run({{"operation","start"}});source.run({{"operation","choose"},{"choice","b"}});auto snapshot=source.checkpoint();auto callCount=calls.size();resume.resume(snapshot);assert(calls.size()==callCount&&resume.status()==source.status());auto broken=snapshot;broken["candidate"]={6,6,6,6,6};AutoTune reject(callback,temp.path());bool badSnapshot=false;try{reject.resume(broken);}catch(...){badSnapshot=true;}assert(badSnapshot&&!reject.status()["active"].get<bool>()&&calls.size()==callCount);for(int i=1;i<10;i++)resume.run({{"operation","choose"},{"choice","b"}});assert(resume.status()["profile_a"]==J({4,4,4,4,4}));std::cout<<"Tone waveform, bounded A/B preference steps, fixed volume and restore checks passed\n";}
